package cn.mop.adapters.monitoring;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import static org.junit.jupiter.api.Assertions.*;
class ZabbixEventPullerTest {
    final UUID pool=UUID.randomUUID();
    ZabbixEventPuller.Query q(int size){return new ZabbixEventPuller.Query(pool,"1","18446744073709551615",100,200,size);}
    ObjectNode row(String id){var r=ZabbixReadClient.JSON.createObjectNode();r.put("eventid",id).put("source","0").put("object","0").put("objectid","101").put("clock","123").put("ns","123456789").put("value","1").put("severity","4").put("r_eventid","0");r.putArray("hosts").addObject().put("hostid","201");return r;}
    ArrayNode rows(ObjectNode...rows){var a=ZabbixReadClient.JSON.createArrayNode();for(var r:rows)a.add(r);return a;}
    @Test void readUsesOnlyExplicitBoundedTriggerParameters(){var params=new AtomicReference<Map<String,Object>>();var p=new ZabbixEventPuller(pool,x->{params.set(x);return rows(row("1"));}).read(q(10));assertEquals(0,params.get().get("source"));assertEquals(0,params.get().get("object"));assertEquals(11,params.get().get("limit"));assertEquals("1",params.get().get("eventid_from"));assertEquals(q(10).lastEventId(),params.get().get("eventid_till"));assertEquals(List.of("eventid"),params.get().get("sortfield"));assertFalse(params.get().containsKey("value"));assertEquals(1,p.events().size());assertFalse(p.completeWindowClaimed());assertFalse(p.durablyStored());assertFalse(p.mappingVerified());}
    @Test void wrongPoolRejectedBeforeTransport(){var p=new ZabbixEventPuller(UUID.randomUUID(),x->{fail("no call");return null;});assertThrows(IllegalArgumentException.class,()->p.read(q(1)));}
    @Test void probeRowPreservesNextPageWithoutCommittingWatermark(){var p=ZabbixEventPuller.decode(q(2),rows(row("1"),row("3"),row("9")));assertEquals(List.of("1","3"),p.events().stream().map(ZabbixEventPuller.SourceEvent::eventId).toList());assertEquals("4",p.nextEventId());assertTrue(p.hasMore());assertEquals("1",p.query().firstEventId());}
    @Test void unsignedMaximumAndNumericOrderingPreserved(){var p=ZabbixEventPuller.decode(q(3),rows(row("9"),row("10"),row("18446744073709551615")));assertEquals("18446744073709551615",p.events().get(2).eventId());assertNull(p.nextEventId());}
    @Test void recoveryAndNanosAreNotLost(){var r=row("1").put("value","0");var p=ZabbixEventPuller.decode(q(1),rows(r));assertEquals(0,p.events().get(0).value());assertEquals(123456789,p.events().get(0).occurredAt().getNano());assertEquals(123,p.events().get(0).occurredAt().getEpochSecond());}
    @Test void emptyPageDoesNotClaimHealthyOrComplete(){var p=ZabbixEventPuller.decode(q(5),rows());assertTrue(p.events().isEmpty());assertFalse(p.hasMore());assertFalse(p.completeWindowClaimed());}
    @Test void allHostCandidatesPreservedWithoutChoosingOne(){var r=row("1");r.withArray("hosts").addObject().put("hostid","202");var p=ZabbixEventPuller.decode(q(1),rows(r));assertEquals(List.of("201","202"),p.events().get(0).hostIds());r.withArray("hosts").removeAll();assertTrue(ZabbixEventPuller.decode(q(1),rows(r)).events().get(0).hostIds().isEmpty());}
    @Test void duplicateHostOrUnexpectedHostFieldRejected(){var r=row("1");r.withArray("hosts").addObject().put("hostid","201");assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(1),rows(r)));var other=row("1");((ObjectNode)other.withArray("hosts").get(0)).put("ip","private");assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(1),rows(other)));}
    @ParameterizedTest @ValueSource(strings={"0","01","-1","1.0","18446744073709551616","x"}) void malformedEventIdsRejected(String id){assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(1),rows(row(id))));}
    @Test void duplicateOrDescendingIdsRejected(){assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(2),rows(row("1"),row("1"))));assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(2),rows(row("10"),row("9"))));}
    @Test void sourceAndObjectCannotDrift(){for(String field:List.of("source","object")){var r=row("1").put(field,"1");assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(1),rows(r)));}}
    @Test void invalidNumbersAndOutOfWindowRowsRejected(){for(var entry:Map.of("clock","201","ns","1000000000","value","2","severity","6").entrySet()){var r=row("1").put(entry.getKey(),entry.getValue());assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(1),rows(r)));}var numeric=row("1").put("clock",123);assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(1),rows(numeric)));}
    @Test void unexpectedFieldsAndMissingFieldsRejected(){var a=row("1").put("name","unexpected");var b=row("1");b.remove("r_eventid");for(var r:List.of(a,b))assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(1),rows(r)));}
    @Test void oversizedPageNotSilentlyTruncated(){assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(1),rows(row("1"),row("2"),row("3"))));}
    @Test void invalidProbeRowRejectsWholePage(){assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(q(1),rows(row("1"),row("0"))));}
    @Test void boundedQueriesAndOutOfRangeResponses(){assertThrows(IllegalArgumentException.class,()->new ZabbixEventPuller.Query(pool,"2","1",100,200,1));assertThrows(IllegalArgumentException.class,()->new ZabbixEventPuller.Query(pool,"1","9",200,100,1));assertThrows(IllegalArgumentException.class,()->q(1001));var limited=new ZabbixEventPuller.Query(pool,"2","8",100,200,2);assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(limited,rows(row("1"))));assertThrows(ZabbixEventPuller.Failure.class,()->ZabbixEventPuller.decode(limited,rows(row("9"))));}
    @Test void upstreamErrorsAreRedacted(){var p=new ZabbixEventPuller(pool,x->{throw new IllegalStateException("private-token-and-url");});var e=assertThrows(ZabbixEventPuller.Failure.class,()->p.read(q(1)));assertFalse(e.toString().contains("private-token"));assertNull(e.getCause());}
    @Test void resultsCannotBeMutatedAndDoNotLogIdentities(){var p=ZabbixEventPuller.decode(q(1),rows(row("1")));assertThrows(UnsupportedOperationException.class,()->p.events().clear());assertThrows(UnsupportedOperationException.class,()->p.events().get(0).hostIds().clear());assertFalse(p.events().get(0).toString().contains("201"));assertFalse(p.toString().contains(pool.toString()));}
}
